```python
def normalize_identity(value):
    return " ".join(str(value or "").split()).casefold()

def participant_is_sibling(participant):
    participant_email = normalize_identity(participant.get("email"))
    participant_name = normalize_identity(participant.get("name"))
    return (
        (participant_email and participant_email in sibling_emails)
        or (participant_name and participant_name in sibling_names)
    )

def transaction_matches_request(transaction):
    return (
        parse_calendar_date(transaction["created_at"]) == yesterday
        and (
            participant_is_sibling(transaction["sender"])
            or participant_is_sibling(transaction["receiver"])
        )
    )

target_transactions_by_id = {}
for transaction in social_feed:
    if transaction_matches_request(transaction):
        target_transactions_by_id[transaction["transaction_id"]] = transaction
