After the mutations, the full public feed must be re-read to verify both that the derived target set still covers every matching transaction and that each target's like count increased.

```python
verification_feed_page_index = 0
verification_social_feed = []
while True:
    verification_feed_page = apis.venmo.show_social_feed(
        access_token=venmo_access_token,
        page_index=verification_feed_page_index,
        page_limit=feed_page_limit,
    )
    verification_social_feed.extend(verification_feed_page)
    if len(verification_feed_page) < feed_page_limit:
        break
    verification_feed_page_index += 1

verification_feed_by_id = {
    transaction["transaction_id"]: transaction
    for transaction in verification_social_feed
}
post_matching_ids = {
    transaction["transaction_id"]
    for transaction in verification_social_feed
    if transaction_matches_request(transaction)
}
coverage_verified = post_matching_ids == set(target_transaction_ids)
like_increase_verified = {
    transaction_id: (
        transaction_id in verification_feed_by_id
        and verification_feed_by_id[transaction_id]["like_count"] >= target_before_like_counts[transaction_id] + 1
    )
    for transaction_id in target_transaction_ids
}
all_postconditions_verified = coverage_verified and all(like_increase_verified.values())
verification_summary = {
    "target_count": len(target_transaction_ids),
    "post_read_matching_count": len(post_matching_ids),
    "increased_like_count": sum(1 for verified in like_increase_verified.values() if verified),
    "coverage_verified": coverage_verified,
    "all_postconditions_verified": all_postconditions_verified,
}
print(verification_summary)
if not all_postconditions_verified:
    raise RuntimeError("Venmo transaction-like postcondition verification failed")
